// assets

//meshes (platform, pots, water, ring) are generated by make-pots.js into dist/pots.pnct:
Load< MeshBuffer > pot_meshes(LoadTagDefault, []() -> MeshBuffer const * {
	return new MeshBuffer(data_path("pots.pnct"));
});

Load< GLuint > pot_meshes_for_lit_color_texture_program(LoadTagDefault, []() -> GLuint const * {
	return new GLuint(pot_meshes->make_vao_for_program(lit_color_texture_program->program));
});

//fonts: prefer the font we ship next to the executable; fall back on common system fonts so the game still runs
static Font *make_font(unsigned int pixel_height) {
	std::string candidates[] = {
		data_path("font.ttf"),
		"C:/Windows/Fonts/arialbd.ttf",
		"/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf",
		"/System/Library/Fonts/Supplemental/Arial Bold.ttf"
	};
	for (auto const &path : candidates) {
		if (std::ifstream(path).good()) return new Font(path, pixel_height);
	}
	throw std::runtime_error("Could not find a font: put a .ttf at dist/font.ttf");
}
Load< Font > ui_font(LoadTagDefault, []() -> Font const * { return make_font(44); });
Load< Font > big_font(LoadTagDefault, []() -> Font const * { return make_font(120); });

//one colour per pot mesh ("Pot0".."Pot7" in the mesh file; keep in sync with make-pots.js):
static const glm::u8vec4 PotColors[Game::MaxPlayers] = {
	glm::u8vec4(0xf0, 0x55, 0x4a, 0xff), glm::u8vec4(0x55, 0x92, 0xf2, 0xff),
	glm::u8vec4(0xf5, 0xd0, 0x45, 0xff), glm::u8vec4(0x60, 0xd0, 0x70, 0xff),
	glm::u8vec4(0xc0, 0x78, 0xe8, 0xff), glm::u8vec4(0xf5, 0x90, 0x3a, 0xff),
	glm::u8vec4(0x50, 0xd8, 0xdc, 0xff), glm::u8vec4(0xf5, 0x8a, 0xb8, 0xff)
};

//----------------------------------------------------------------------------

//sets up a drawable that draws the named mesh from pots.pnct with the lit shader:
static Scene::Drawable *add_drawable(Scene &scene, Scene::Transform *transform, std::string const &mesh_name) {
	scene.drawables.emplace_back(transform);
	Scene::Drawable &drawable = scene.drawables.back();
	Mesh const &mesh = pot_meshes->lookup(mesh_name);

	drawable.pipeline = lit_color_texture_program_pipeline;
	drawable.pipeline.vao = *pot_meshes_for_lit_color_texture_program;
	drawable.pipeline.type = mesh.type;
	drawable.pipeline.start = mesh.start;
	drawable.pipeline.count = mesh.count;
	//the scene doesn't have a light loop yet, so each drawable sets the (single, directional) light itself:
	drawable.pipeline.set_uniforms = [](){
		glUniform1i(lit_color_texture_program->LIGHT_TYPE_int, 3);
		glm::vec3 dir = glm::normalize(glm::vec3(-0.35f, 0.45f, -1.0f));
		glUniform3fv(lit_color_texture_program->LIGHT_DIRECTION_vec3, 1, glm::value_ptr(dir));
		glUniform3fv(lit_color_texture_program->LIGHT_ENERGY_vec3, 1, glm::value_ptr(glm::vec3(1.0f, 0.96f, 0.88f)));
	};
	return &drawable;
}

static void set_mesh(Scene::Drawable *drawable, std::string const &mesh_name) {
	Mesh const &mesh = pot_meshes->lookup(mesh_name);
	drawable->pipeline.start = mesh.start;
	drawable->pipeline.count = mesh.count;
}

static void hide(Scene::Drawable *drawable) { drawable->pipeline.count = 0; }

PlayMode::PlayMode(Client &client_) : client(client_) {
	//water:
	{
		scene.transforms.emplace_back();
		Scene::Transform *t = &scene.transforms.back();
		t->name = "Water";
		t->position = glm::vec3(0.0f, 0.0f, -3.0f);
		add_drawable(scene, t, "Water");
	}
	//platform:
	{
		scene.transforms.emplace_back();
		platform_transform = &scene.transforms.back();
		platform_transform->name = "Platform";
		add_drawable(scene, platform_transform, "Platform");
	}
	//local-player marker:
	{
		scene.transforms.emplace_back();
		marker_transform = &scene.transforms.back();
		marker_transform->name = "Marker";
		marker_drawable = add_drawable(scene, marker_transform, "Ring");
		hide(marker_drawable);
	}
	//pots:
	for (auto &v : visuals) {
		scene.transforms.emplace_back();
		v.transform = &scene.transforms.back();
		v.transform->name = "Pot";
		v.drawable = add_drawable(scene, v.transform, "Pot0");
		hide(v.drawable);
	}
	//splashes:
	for (auto &s : splashes) {
		scene.transforms.emplace_back();
		s.transform = &scene.transforms.back();
		s.transform->name = "Splash";
		s.drawable = add_drawable(scene, s.transform, "Ring");
		hide(s.drawable);
	}
	//camera:
	{
		scene.transforms.emplace_back();
		Scene::Transform *t = &scene.transforms.back();
		t->name = "Camera";
		t->position = glm::vec3(0.0f, -9.5f, 8.5f);
		glm::vec3 forward = glm::normalize(glm::vec3(0.0f, 0.0f, 0.2f) - t->position);
		glm::vec3 right = glm::normalize(glm::cross(forward, glm::vec3(0.0f, 0.0f, 1.0f)));
		glm::vec3 up = glm::cross(right, forward);
		t->rotation = glm::quat_cast(glm::mat3(right, up, -forward));
		scene.cameras.emplace_back(t);
		camera = &scene.cameras.back();
		camera->fovy = glm::radians(42.0f);
		camera->near = 0.1f;
	}
}

PlayMode::~PlayMode() {
}

bool PlayMode::handle_event(SDL_Event const &evt, glm::uvec2 const &window_size) {
	if (evt.type != SDL_EVENT_KEY_DOWN && evt.type != SDL_EVENT_KEY_UP) return false;

	Button *button = nullptr;
	switch (evt.key.key) {
		case SDLK_A: case SDLK_LEFT: button = &controls.left; break;
		case SDLK_D: case SDLK_RIGHT: button = &controls.right; break;
		case SDLK_W: case SDLK_UP: button = &controls.up; break;
		case SDLK_S: case SDLK_DOWN: button = &controls.down; break;
		case SDLK_SPACE: button = &controls.jump; break;
		default: return false;
	}
	if (evt.type == SDL_EVENT_KEY_DOWN) {
		if (!evt.key.repeat) {
			button->downs += 1;
			button->pressed = true;
		}
	} else {
		button->pressed = false;
	}
	return true;
}

void PlayMode::update(float elapsed) {
	time += elapsed;

	//queue data for sending to server:
	controls.send_controls_message(&client.connection);

	//reset button press counters:
	controls.left.downs = 0;
	controls.right.downs = 0;
	controls.up.downs = 0;
	controls.down.downs = 0;
	controls.jump.downs = 0;

	//send/receive data:
	got_state = false;
	client.poll([this](Connection *c, Connection::Event event){
		if (event == Connection::OnOpen) {
			std::cout << "[" << c->socket << "] opened" << std::endl;
		} else if (event == Connection::OnClose) {
			std::cout << "[" << c->socket << "] closed (!)" << std::endl;
			throw std::runtime_error("Lost connection to server!");
		} else { assert(event == Connection::OnRecv);
			bool handled_message;
			try {
				do {
					handled_message = false;
					if (game.recv_state_message(c)) { handled_message = true; got_state = true; }
				} while (handled_message);
			} catch (std::exception const &e) {
				std::cerr << "[" << c->socket << "] malformed message from server: " << e.what() << std::endl;
				//quit the game:
				throw e;
			}
		}
	}, 0.0);

	//---- fold the newest snapshot into the visuals ----
	std::array< bool, Game::MaxPlayers > seen;
	seen.fill(false);
	for (auto const &p : game.players) {
		//find this player's visual (by id), or claim a free one:
		Visual *v = nullptr;
		for (auto &cand : visuals) if (cand.active && cand.id == p.id) { v = &cand; break; }
		if (!v) {
			for (auto &cand : visuals) if (!cand.active) { v = &cand; break; }
			if (!v) continue; //(server never sends more than MaxPlayers)
			v->active = true;
			v->id = p.id;
			v->pos = v->target = p.position;
			v->vel = p.velocity;
			v->height = p.height;
			v->facing = 0.0f;
			v->fall_time = 0.0f;
			v->splashed = false;
		}
		seen[v - &visuals[0]] = true;

		if (got_state) {
			//big sudden change in velocity == a bump (or a dash): shake the camera a little
			float dv = glm::length(p.velocity - v->vel);
			if (dv > 5.0f) shake = std::max(shake, std::min(0.5f, 0.05f * dv));
			v->target = p.position;
			v->vel = p.velocity;
			if (glm::length(v->target - v->pos) > 2.5f) v->pos = v->target; //teleport (new round)
			if (p.height >= 0.0f) { v->fall_time = 0.0f; v->splashed = false; }
		} else {
			v->target += v->vel * elapsed;
		}
		float ease = 1.0f - std::pow(0.5f, elapsed / 0.045f);
		v->pos = glm::mix(v->pos, v->target, ease);
		v->height = glm::mix(v->height, p.height, 1.0f - std::pow(0.5f, elapsed / 0.03f));
		if (p.falling) v->fall_time += elapsed;

		//turn to face the direction of travel:
		if (glm::length(v->vel) > 0.6f) {
			float want = std::atan2(v->vel.y, v->vel.x);
			float diff = std::remainder(want - v->facing, 2.0f * float(M_PI));
			v->facing += diff * (1.0f - std::pow(0.5f, elapsed / 0.08f));
		}

		//splash when a falling pot reaches the water:
		if (!v->splashed && v->height < -2.9f) {
			v->splashed = true;
			for (auto &s : splashes) {
				if (s.age < 0.0f) {
					s.age = 0.0f;
					s.transform->position = glm::vec3(v->pos, -2.95f);
					break;
				}
			}
		}
	}
	for (uint32_t i = 0; i < visuals.size(); ++i) {
		if (!seen[i]) visuals[i].active = false;
	}

	//---- animate splashes / platform / camera ----
	for (auto &s : splashes) {
		if (s.age < 0.0f) continue;
		s.age += elapsed;
		float t = s.age / 0.8f;
		if (t >= 1.0f) { s.age = -1.0f; hide(s.drawable); continue; }
		set_mesh(s.drawable, "Ring");
		float r = glm::mix(0.5f, 2.6f, 1.0f - (1.0f - t) * (1.0f - t));
		s.transform->scale = glm::vec3(r, r, 1.0f - t);
	}

	platform_radius_shown = glm::mix(platform_radius_shown, game.platform_radius, 1.0f - std::pow(0.5f, elapsed / 0.06f));
	platform_transform->scale = glm::vec3(platform_radius_shown, platform_radius_shown, 1.0f);
	//the platform rumbles slightly as it crumbles:
	if (game.phase == Phase::Playing && game.phase_time > Game::ShrinkDelay && game.platform_radius > Game::PlatformMinRadius + 0.01f) {
		platform_transform->position.z = 0.012f * std::sin(time * 60.0f);
	} else {
		platform_transform->position.z = 0.0f;
	}

	if (game.phase != last_phase) {
		if (game.phase == Phase::Playing) shake = std::max(shake, 0.25f);
		last_phase = game.phase;
	}
	shake = std::max(0.0f, shake - elapsed * 1.6f);
}

void PlayMode::draw(glm::uvec2 const &drawable_size) {
	//---- update scene transforms from visuals ----
	Player const *local = game.players.empty() ? nullptr : &game.players.front();

	for (auto &v : visuals) {
		if (!v.active) { hide(v.drawable); continue; }
		Player const *pp = nullptr;
		for (auto const &p : game.players) if (p.id == v.id) { pp = &p; break; }
		if (!pp) { hide(v.drawable); continue; }
		Player const &p = *pp;

		bool spectating = (!p.alive && !p.falling);
		if (spectating || v.height < -8.5f) { hide(v.drawable); continue; }

		set_mesh(v.drawable, "Pot" + std::to_string(p.color_index % Game::MaxPlayers));
		v.transform->position = glm::vec3(v.pos, v.height);

		glm::quat rot = glm::angleAxis(v.facing + 0.5f * float(M_PI), glm::vec3(0.0f, 0.0f, 1.0f));
		float speed = glm::length(v.vel);
		if (speed > 0.05f && !p.falling) {
			glm::vec3 axis = glm::normalize(glm::cross(glm::vec3(0.0f, 0.0f, 1.0f), glm::vec3(v.vel, 0.0f)));
			rot = glm::angleAxis(std::min(0.45f, 0.05f * speed), axis) * rot;
		}
		if (p.falling) {
			rot = glm::angleAxis(v.fall_time * 3.5f, glm::normalize(glm::vec3(1.0f, 0.35f, 0.0f))) * rot;
		}
		v.transform->rotation = rot;
		//squash while dashing:
		if (p.dash_time > 0.0f) v.transform->scale = glm::vec3(1.1f, 1.1f, 0.88f);
		else v.transform->scale = glm::vec3(1.0f);
	}

	//marker ring under the local pot:
	hide(marker_drawable);
	if (local && local->alive) {
		for (auto &v : visuals) {
			if (!v.active || v.id != local->id) continue;
			set_mesh(marker_drawable, "Ring");
			float r = 0.72f + 0.04f * std::sin(time * 5.0f);
			marker_transform->position = glm::vec3(v.pos, 0.02f);
			marker_transform->scale = glm::vec3(r, r, 1.0f);
		}
	}

	//camera:
	float aspect = float(drawable_size.x) / float(std::max(1u, drawable_size.y));
	camera->aspect = aspect;
	{
		//narrow windows: back the camera off so the whole platform still fits
		float pull = std::max(1.0f, 1.55f / aspect);
		camera->transform->position = glm::vec3(0.0f, -9.5f, 8.5f) * pull;
		glm::vec3 target(0.0f, 0.0f, 0.2f);
		if (shake > 0.0f) {
			target += glm::vec3(std::sin(time * 71.0f), std::cos(time * 83.0f), std::sin(time * 59.0f)) * shake * 0.35f;
		}
		glm::vec3 forward = glm::normalize(target - camera->transform->position);
		glm::vec3 right = glm::normalize(glm::cross(forward, glm::vec3(0.0f, 0.0f, 1.0f)));
		glm::vec3 up = glm::cross(right, forward);
		camera->transform->rotation = glm::quat_cast(glm::mat3(right, up, -forward));
	}

	//---- 3D scene ----
	glClearColor(0.62f, 0.78f, 0.92f, 1.0f);
	glClearDepth(1.0f);
	glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);
	glEnable(GL_DEPTH_TEST);
	glDepthFunc(GL_LESS);

	scene.draw(*camera);

	//---- 2D overlay (text) ----
	glDisable(GL_DEPTH_TEST);
	glEnable(GL_BLEND);
	glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);

	const float W = float(drawable_size.x), H = float(drawable_size.y);
	const float S = H / 1080.0f; //text scale: fonts are rasterized for a 1080p window
	glm::mat4 pixels_to_clip = glm::ortho(0.0f, W, 0.0f, H);
	glm::mat4 world_to_clip = camera->make_projection() * glm::mat4(camera->transform->make_local_from_world());

	{
		TextRenderer text(pixels_to_clip);
		const glm::vec3 X(S, 0.0f, 0.0f), Y(0.0f, S, 0.0f);

		//draws text with a drop shadow; (x,y) is the baseline start in pixels from the bottom-left
		auto put = [&](Font const &font, std::string const &str, float x, float y, glm::u8vec4 col, float align) {
			float width = 0.0f;
			font.layout(str, &width);
			x -= align * width * S;
			text.draw_text(font, str, glm::vec3(x + 2.0f * S, y - 2.0f * S, 0.0f), X, Y, glm::u8vec4(0, 0, 0, 0xb0));
			text.draw_text(font, str, glm::vec3(x, y, 0.0f), X, Y, col);
		};
		const glm::u8vec4 white(0xff), dim(0xe8, 0xe8, 0xe8, 0xff);

		//names floating over pots:
		for (auto const &v : visuals) {
			if (!v.active || !v.drawable->pipeline.count) continue;
			Player const *pp = nullptr;
			for (auto const &p : game.players) if (p.id == v.id) { pp = &p; break; }
			if (!pp || pp->falling) continue;
			glm::vec4 clip = world_to_clip * glm::vec4(v.pos.x, v.pos.y, v.height + 1.35f, 1.0f);
			if (clip.w <= 0.0f) continue;
			glm::vec2 ndc = glm::vec2(clip) / clip.w;
			put(*ui_font, pp->name, (ndc.x * 0.5f + 0.5f) * W, (ndc.y * 0.5f + 0.5f) * H, PotColors[pp->color_index % Game::MaxPlayers], 0.5f);
		}

		//scoreboard:
		{
			float y = H - 70.0f * S;
			put(*ui_font, "ROUND " + std::to_string(game.round_number), 40.0f * S, y, dim, 0.0f);
			y -= 58.0f * S;
			for (auto const &p : game.players) {
				std::string line = (&p == local ? "> " : "  ") + p.name + "   " + std::to_string(p.score);
				put(*ui_font, line, 40.0f * S, y, PotColors[p.color_index % Game::MaxPlayers], 0.0f);
				y -= 52.0f * S;
			}
		}

		//find the winner's name:
		std::string winner_name;
		glm::u8vec4 winner_color = white;
		for (auto const &p : game.players) {
			if (p.id == game.winner_id) { winner_name = p.name; winner_color = PotColors[p.color_index % Game::MaxPlayers]; }
		}

		//big centered banner:
		float cx = W * 0.5f, cy = H - 190.0f * S;
		if (game.phase == Phase::Waiting) {
			put(*ui_font, "Waiting for another pot to join...", cx, cy + 60.0f * S, white, 0.5f);
			put(*ui_font, "(start a second client to play)", cx, cy, dim, 0.5f);
		} else if (game.phase == Phase::Countdown) {
			int n = int(std::ceil(Game::CountdownTime - game.phase_time));
			put(*big_font, std::to_string(std::max(1, n)), cx, cy, white, 0.5f);
		} else if (game.phase == Phase::Playing) {
			if (game.phase_time < 0.9f) put(*big_font, "GO!", cx, cy, white, 0.5f);
			if (local && !local->alive && local->in_round) {
				put(*ui_font, "You fell in! Watching the rest...", cx, cy - 20.0f * S, white, 0.5f);
			} else if (local && !local->in_round) {
				put(*ui_font, "Round in progress - you join the next one", cx, cy - 20.0f * S, white, 0.5f);
			}
		} else { //Over
			if (game.winner_id == 255) put(*big_font, "Draw!", cx, cy, white, 0.5f);
			else put(*big_font, winner_name + " wins!", cx, cy, winner_color, 0.5f);
		}

		//dash status and controls:
		if (local) {
			std::string dash;
			if (local->dash_cooldown > 0.0f) {
				//little bar built from characters that every font has:
				int filled = int(std::round(10.0f * (1.0f - local->dash_cooldown / Game::DashCooldown)));
				filled = std::max(0, std::min(10, filled));
				dash = "DASH [" + std::string(filled, '#') + std::string(10 - filled, '-') + "]";
			} else {
				dash = "DASH READY";
			}
			put(*ui_font, dash, cx, 90.0f * S, local->dash_cooldown > 0.0f ? dim : glm::u8vec4(0xff, 0xe0, 0x60, 0xff), 0.5f);
		}
		put(*ui_font, "WASD / arrows: move     SPACE: dash", cx, 36.0f * S, dim, 0.5f);
	}

	glDisable(GL_BLEND);
	GL_ERRORS();
}
